"""Dedicated production IAM/KMS/secrets/recovery storage; no source privileges."""
from common import *
P='growthcast-portal-production';account='059393269249'
ref=lambda n:{'Ref':n};att=lambda n,k:{'Fn::GetAtt':[n,k]}
r={}
def add(n,t,p,**kw):r[n]={'Type':'AWS::'+t,'Properties':p,**kw}
trust={'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'ecs-tasks.amazonaws.com'},'Action':'sts:AssumeRole','Condition':{'StringEquals':{'aws:SourceAccount':account},'ArnLike':{'aws:SourceArn':'arn:aws:ecs:us-east-1:'+account+':*'}}}]}
for name in ['Runtime','Backup','Restore']:
 add(name+'Role','IAM::Role',{'RoleName':P+'-'+name.lower(),'AssumeRolePolicyDocument':trust})
 add(name+'Key','KMS::Key',{'Description':P+' '+name.lower()+' secrets','EnableKeyRotation':True,'KeyPolicy':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'AWS':'arn:aws:iam::'+account+':root'},'Action':'kms:*','Resource':'*'}]}},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
for name,key in [('Runtime','Runtime'),('Connection','Runtime'),('Backup','Backup')]:
 add(name+'Secret','SecretsManager::Secret',{'Name':'growthcast/portal/production/'+name.lower(),'KmsKeyId':att(key+'Key','Arn')},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
add('RuntimeAccess','IAM::Policy',{'PolicyName':'production-runtime-only','Roles':[ref('RuntimeRole')],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'secretsmanager:GetSecretValue','Resource':[ref('RuntimeSecret'),ref('ConnectionSecret')]},{'Effect':'Allow','Action':'kms:Decrypt','Resource':att('RuntimeKey','Arn'),'Condition':{'StringEquals':{'kms:ViaService':'secretsmanager.us-east-1.amazonaws.com','kms:EncryptionContext:SecretARN':[ref('RuntimeSecret'),ref('ConnectionSecret')]}}}]}})
add('ExecutionRole','IAM::Role',{'RoleName':P+'-execution','AssumeRolePolicyDocument':trust,'ManagedPolicyArns':['arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy']})
add('Images','ECR::Repository',{'RepositoryName':P,'ImageTagMutability':'IMMUTABLE','ImageScanningConfiguration':{'ScanOnPush':True}},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
add('Logs','Logs::LogGroup',{'LogGroupName':'/growthcast/portal/production','RetentionInDays':30},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
add('Archive','S3::Bucket',{'BucketName':P+'-recovery-'+account,'VersioningConfiguration':{'Status':'Enabled'},'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'BlockPublicPolicy':True,'IgnorePublicAcls':True,'RestrictPublicBuckets':True},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'LifecycleConfiguration':{'Rules':[{'Id':'archive-retention','Prefix':'production/','Status':'Enabled','ExpirationInDays':30,'NoncurrentVersionExpiration':{'NoncurrentDays':30}}]}},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
bucket=att('Archive','Arn');objects={'Fn::Join':['',[bucket,'/production/*']]};records={'Fn::Join':['',[bucket,'/verification/production/*']]}
add('ArchivePolicy','S3::BucketPolicy',{'Bucket':ref('Archive'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[bucket,{'Fn::Join':['',[bucket,'/*']]}],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}]}})
add('BackupAccess','IAM::Policy',{'PolicyName':'production-capture-only','Roles':[ref('BackupRole')],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'secretsmanager:GetSecretValue','Resource':ref('BackupSecret')},{'Effect':'Allow','Action':'kms:Decrypt','Resource':att('BackupKey','Arn'),'Condition':{'StringEquals':{'kms:ViaService':'secretsmanager.us-east-1.amazonaws.com','kms:EncryptionContext:SecretARN':ref('BackupSecret')}}},{'Effect':'Allow','Action':'kms:Encrypt','Resource':att('RestoreKey','Arn'),'Condition':{'StringEquals':{'kms:EncryptionContext:project':P},'StringLike':{'kms:EncryptionContext:archive':'production/*'}}},{'Effect':'Allow','Action':'s3:PutObject','Resource':objects,'Condition':{'StringEquals':{'s3:x-amz-server-side-encryption':'AES256'},'Null':{'s3:if-none-match':'false'}}},{'Effect':'Allow','Action':'cloudwatch:PutMetricData','Resource':'*','Condition':{'StringEquals':{'cloudwatch:namespace':'GrowthCast/PortalRecovery'}}}]}})
add('RestoreAccess','IAM::Policy',{'PolicyName':'production-restore-only','Roles':[ref('RestoreRole')],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'s3:GetObjectVersion','Resource':[objects,records]},{'Effect':'Allow','Action':'s3:PutObject','Resource':records,'Condition':{'StringEquals':{'s3:x-amz-server-side-encryption':'AES256'},'Null':{'s3:if-none-match':'false'}}},{'Effect':'Allow','Action':'kms:Decrypt','Resource':att('RestoreKey','Arn'),'Condition':{'StringEquals':{'kms:EncryptionContext:project':P},'StringLike':{'kms:EncryptionContext:archive':'production/*'}}}]}})
outputs={**{n+'SecretArn':ref(n+'Secret') for n in ['Runtime','Connection','Backup']},**{n+'RoleArn':att(n+'Role','Arn') for n in ['Runtime','Backup','Restore','Execution']},**{n+'KeyArn':att(n+'Key','Arn') for n in ['Runtime','Backup','Restore']},'Repository':att('Images','RepositoryUri'),'Bucket':ref('Archive'),'LogGroup':ref('Logs')}
t={'AWSTemplateFormatVersion':'2010-09-09','Description':'Independent GrowthCast Phase 2 production foundation','Resources':r,'Outputs':{k:{'Value':v} for k,v in outputs.items()}}
save(R/'foundation.json',t)
if __name__=='__main__':
 assert not (R/'foundation-resources.json').exists()
 save(R/'foundation-resources.json',a.create_stack(P+'-foundation',t));print('Production-only roles, keys, secret containers and backup storage created.',flush=True)
